window.VO = [{"id":"a1","scene":"button","text":"Every app that lets customers bring their own domain has this button.","t0":0.8152,"t1":5.0155,"beat0":1.25,"beat1":7.69},{"id":"a2","scene":"button","text":"What happens after the click decides whether they ever go live.","t0":5.3804,"t1":9.0661,"beat0":8.25,"beat1":13.901},{"id":"b1","scene":"context","text":"Your customers can buy a domain from over a hundred different websites.","t0":10.1087,"t1":14.4403,"beat0":15.5,"beat1":22.142},{"id":"b2","scene":"context","text":"And most of them use more than one.","t0":15,"t1":17.2066,"beat0":23,"beat1":26.383},{"id":"b3","scene":"context","text":"A shop here. A blog there. An old idea from years ago.","t0":17.6087,"t1":21.4171,"beat0":27,"beat1":32.84},{"id":"c1","scene":"usual","text":"Today, that click usually hands your customer a list of DNS records. And a job.","t0":22.337,"t1":27.913,"beat0":34.25,"beat1":42.8},{"id":"c2","scene":"usual","text":"First, remember where the domain was bought.","t0":28.6957,"t1":31.2334,"beat0":44,"beat1":47.891},{"id":"c3","scene":"usual","text":"Then leave your app and sign in somewhere else. Forgot the password? Reset it.","t0":31.6304,"t1":36.6368,"beat0":48.5,"beat1":56.176},{"id":"c4","scene":"usual","text":"Hunt through the menus for the DNS settings.","t0":37.0109,"t1":39.791,"beat0":56.75,"beat1":61.013},{"id":"c5","scene":"usual","text":"Copy every record by hand, exactly right.","t0":40.1087,"t1":43.2273,"beat0":61.5,"beat1":66.282},{"id":"c6","scene":"usual","text":"Then wait, and hope.","t0":43.5326,"t1":44.8625,"beat0":66.75,"beat1":68.789},{"id":"c7","scene":"usual","text":"One wrong character, and the domain never connects. That's where customers give up, or open a support ticket.","t0":45.3261,"t1":52.3704,"beat0":69.5,"beat1":80.301},{"id":"d1","scene":"turn","text":"Custom Domain takes all of that off their plate.","t0":53.4783,"t1":56.25,"beat0":82,"beat1":86.25},{"id":"e1","scene":"ours","text":"Same app. Same button. They type their domain once.","t0":57.0652,"t1":60.4574,"beat0":87.5,"beat1":92.701},{"id":"e2","scene":"ours","text":"We automatically detect where the domain is managed.","t0":60.8152,"t1":64.2094,"beat0":93.25,"beat1":98.454},{"id":"e3","scene":"ours","text":"Then, without leaving your app, they sign in to that provider, and approve once.","t0":64.5652,"t1":69.3566,"beat0":99,"beat1":106.347},{"id":"e4","scene":"ours","text":"That's it for your customer.","t0":69.9457,"t1":71.4762,"beat0":107.25,"beat1":109.597},{"id":"e5","scene":"ours","text":"Behind the scenes, we add the exact DNS records, check that they resolve, and issue the HTTPS certificate.","t0":72.3913,"t1":80.5388,"beat0":111,"beat1":123.493},{"id":"e6","scene":"ours","text":"The domain is live. Connected correctly, the first time.","t0":81.0326,"t1":84.6308,"beat0":124.25,"beat1":129.767},{"id":"e7","scene":"ours","text":"And we keep it that way. We check it every hour, and renew certificates before they expire.","t0":85.2717,"t1":90.8932,"beat0":130.75,"beat1":139.37},{"id":"f1","scene":"compare","text":"Seven steps across two websites, or one sign-in that never leaves your app.","t0":91.7935,"t1":96.376,"beat0":140.75,"beat1":147.776},{"id":"g1","scene":"end","text":"Custom Domain. Your customers should never touch DNS.","t0":97.337,"t1":100.985,"beat0":149.25,"beat1":154.844}];
